package com.scriptles.cabinet.profile.service;
import com.scriptles.cabinet.common.api.ApiException; import com.scriptles.cabinet.profile.dto.*; import com.scriptles.cabinet.profile.entity.*; import com.scriptles.cabinet.profile.enums.*; import com.scriptles.cabinet.profile.repository.*; import com.scriptles.cabinet.user.entity.User; import com.scriptles.cabinet.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class HQClaimService { private final HQProfileRepository hqs; private final HQClaimRepository claims; private final HQMemberRepository members; private final UserRepository users;
 @Transactional(readOnly=true) public java.util.List<ClaimResponse> mine(UUID accountId){ return claims.findByRequestedByIdOrderByCreatedAtDesc(accountId).stream().map(this::to).toList(); }
 @Transactional public ClaimResponse submit(UUID accountId,UUID profileId,ClaimRequest req){ HQProfile hq=hqs.findByProfileId(profileId).orElseThrow(()->err("PROFILE_NOT_FOUND","Perfil não encontrado")); if(hq.getClaimStatus()!=HQClaimStatus.UNCLAIMED) throw err("HQ_NOT_CLAIMABLE","Este perfil não pode ser reivindicado"); if(claims.existsByHqProfileIdAndRequestedByIdAndStatusIn(hq.getId(),accountId,List.of(HQClaimRequestStatus.PENDING,HQClaimRequestStatus.REQUIRES_INFORMATION))) throw err("ACTIVE_CLAIM_EXISTS","Já existe uma solicitação ativa"); HQClaim c=new HQClaim();c.setHqProfile(hq);c.setRequestedBy(users.findById(accountId).orElseThrow());c.setOrganizationEmail(req.organizationEmail().trim().toLowerCase(Locale.ROOT));c.setEvidenceUrl(req.evidenceUrl());c.setMessage(req.message());c=claims.save(c);hq.setClaimStatus(HQClaimStatus.CLAIM_PENDING);return to(c); }
 @Transactional public ClaimResponse decide(UUID reviewerId,UUID claimId,HQClaimRequestStatus status){ if(!users.findById(reviewerId).map(u->u.getRole()!=null&&u.getRole().canModerate()).orElse(false)) throw err("HQ_FORBIDDEN","Apenas moderadores podem revisar claims"); HQClaim c=claims.findById(claimId).orElseThrow(()->err("CLAIM_NOT_FOUND","Claim não encontrada")); if(c.getStatus()!=HQClaimRequestStatus.PENDING&&status!=HQClaimRequestStatus.REQUIRES_INFORMATION) throw err("INVALID_CLAIM_STATE","Estado de claim inválido"); c.setStatus(status);c.setReviewedBy(users.findById(reviewerId).orElseThrow());c.setReviewedAt(Instant.now()); if(status==HQClaimRequestStatus.APPROVED){ c.getHqProfile().setClaimStatus(HQClaimStatus.CLAIMED); Profile p=c.getHqProfile().getProfile();p.setVerified(true);p.setVerifiedAt(Instant.now()); if(!members.existsByHqProfileIdAndAccountId(c.getHqProfile().getId(),c.getRequestedBy().getId())){HQMember m=new HQMember();m.setHqProfile(c.getHqProfile());m.setAccount(c.getRequestedBy());m.setRole(HQMemberRole.OWNER);members.save(m);} } else if(status==HQClaimRequestStatus.REJECTED){c.getHqProfile().setClaimStatus(HQClaimStatus.UNCLAIMED);} return to(c); }
 private ClaimResponse to(HQClaim c){return new ClaimResponse(c.getId(),c.getHqProfile().getId(),c.getStatus(),c.getOrganizationEmail(),c.getEvidenceUrl(),c.getMessage(),c.getCreatedAt());} private ApiException err(String c,String m){return new ApiException(HttpStatus.FORBIDDEN,c,m);} }
